class Group:
    def __init__(self, members: list[str]) -> None:
        self.members = list(members)
        self._balances: dict[str, float] = {m: 0.0 for m in self.members}

    def add_expense(self, payer: str, amount: float,
                    participants: list[str] | None = None) -> None:
        if payer not in self._balances:
            raise ValueError(f"Unknown payer: {payer}")
        if participants is None:
            participants = list(self.members)
        else:
            participants = list(participants)
            for p in participants:
                if p not in self._balances:
                    raise ValueError(f"Unknown participant: {p}")
        if not participants:
            participants = list(self.members)
        if amount < 0:
            raise ValueError("Amount must be non-negative")

        n = len(participants)
        # Split into cents
        total_cents = round(amount * 100)
        cents_each = total_cents // n
        # The payer bears the remainder (leftover cents)
        remainder = total_cents - cents_each * n

        for p in participants:
            if p == payer:
                # payer's share includes the remainder
                share_cents = cents_each + remainder
            else:
                share_cents = cents_each
            self._balances[p] -= share_cents / 100.0
        # Payer paid the whole amount
        self._balances[payer] += total_cents / 100.0

    def balances(self) -> dict[str, float]:
        return {m: round(v, 2) for m, v in self._balances.items()}

    def settle_up(self) -> list[tuple[str, str, float]]:
        # Work in cents to avoid floating point issues
        cents = {m: round(v * 100) for m, v in self._balances.items()}

        debtors = [(m, -c) for m, c in cents.items() if c < 0]
        creditors = [(m, c) for m, c in cents.items() if c > 0]

        # Sort for deterministic output: largest debts first
        debtors.sort(key=lambda x: -x[1])
        creditors.sort(key=lambda x: -x[1])

        payments: list[tuple[str, str, float]] = []
        i = j = 0
        while i < len(debtors) and j < len(creditors):
            debtor, debt = debtors[i]
            creditor, credit = creditors[j]
            pay = min(debt, credit)

            if pay >= 100:  # only propose payments >= 1.00
                payments.append((debtor, creditor, pay / 100.0))

            debt -= pay
            credit -= pay

            if debt == 0:
                i += 1
            else:
                debtors[i] = (debtor, debt)
            if credit == 0:
                j += 1
            else:
                creditors[j] = (creditor, credit)

        return payments
